script:
if (-not $RULE_NAME) { throw 'RULE_NAME is required' }
$port = if ($LOCAL_PORT) { $LOCAL_PORT } else { '8443' }
$proto = if ($PROTOCOL) { $PROTOCOL } else { 'TCP' }
Remove-NetFirewallRule -Name $RULE_NAME -ErrorAction Ignore
$desc = if ($DESCRIPTION) { $DESCRIPTION } else { 'Meridian sync channel' }
New-NetFirewallRule -Name $RULE_NAME -DisplayName $RULE_NAME -Description $desc -Direction Inbound -Protocol $proto -LocalPort $port -Action Allow -Profile Any | Out-Null
